"""recon.py — reconciliere UNIFICATĂ SAGA ↔ iDempiere, într-un singur script.

READ-ONLY. Citește ambele baze direct și, într-o singură rulare:
  1. potrivește fiecare entitate pe CHEIA REALĂ din scripturile f1-f21 (parteneri, produse, conturi,
     facturi, plăți, active, angajați) → dovada de completitudine rând-cu-rând;
  2. verifică GL echilibrat (Σdebit = Σcredit) + totalurile de bani pe facturi;
  3. dă un verdict final.

Chei (din citirea f1-f21):
  conturi (F2)   CONTURI.CONT                → c_elementvalue.value  (F2 sare analiticele terți ^(40|41|46|419) cu '.')
  parteneri (F3) CLIENTI/FURNIZORI.ANALITIC  → c_bpartner.value = <CC>:<ANALITIC>
  produse (F4)   ARTICOLE.COD                → m_product.value       (dedup -2/-3 la COD duplicat)
  facturi (F6)   NR_IESIRE/NR_INTRARE [+-ID] → c_invoice.documentno  (sufix -<ID_*> la NR duplicat)
  plăți (F7)     NOTE_FACTURI.ID_NOTA        → c_payment.documentno = P<ID_NOTA> (fără storno)
  active (F9)    PVR.NRINV                   → a_asset.inventoryno   (cost = PVR.VAL)
  angajați (F10) SALARIATI.COD               → c_bpartner.value = <CC>:SAL:<COD> (dedup pe CN)

Rulare (din containerul backend, care vede ambele baze):
    docker cp recon.py eva-contab-backend:/tmp/ && \
    docker exec eva-contab-backend python3 /tmp/recon.py --client 1000000 --schema saga_cesiro_37705493
"""
from __future__ import annotations

import argparse
import os
import re
from collections import Counter

import psycopg

SAGA_DSN = os.environ.get("RECON_SAGA_DSN",
    "host=postgres-eva port=5432 dbname=eva user=eva password=eva_local_dev connect_timeout=8")
IDMP_DSN = os.environ.get("RECON_IDMP_DSN",
    "host=eva-postgres-cesiro port=5432 dbname=idempiere user=adempiere password=adempiere connect_timeout=8")

G = "\033[32m"; Y = "\033[33m"; R = "\033[31m"; B = "\033[1m"; X = "\033[0m"


def num(s):
    s = str(s or "").strip()
    return float(s.replace(",", ".")) if re.match(r"^-?[0-9]+([.,][0-9]+)?$", s) else 0.0


def mark(missing, total):
    tol = max(5, total * 0.01)
    if missing == 0:
        return G, "✓"
    if missing <= tol:
        return G, "✓"
    return (Y, "⚠") if missing <= total * 0.03 else (R, "✗")


class Recon:
    def __init__(self, schema, cid, sdsn, idsn):
        self.schema, self.cid = schema, cid
        self.sc = psycopg.connect(sdsn)
        self.ic = psycopg.connect(idsn)
        self.ccode = self._ccode()
        self.rows = []          # (nume, saga_n, matched, missing, col, mk)
        self.notes = []         # observații

