    public static TableReport runTable(ImportCtx ctx, SagaArchive archive, String tableName)
            throws Exception {
        SagaTableImporter imp = ImportRegistry.of(tableName);
        if (imp == null) {
            throw new IllegalArgumentException("tabelă necunoscută: " + tableName);
        }
        // Sesiunea firmei se împrumută și AICI, nu doar în rularea completă: procesele native
        // (Import_Invoice, Import_BPartner…) își iau rolul cu MRole.getDefault() fără
        // argumente, adică din contextul GLOBAL. Fără împrumut, o rulare pe o singură tabelă
        // moare cu «MRole.getDefault() is null» și nu creează niciun document — măsurat pe
        // testhr: 4 rânduri staged, 0 consumate.
        // Aceeași limită ca la rularea completă: o rulare pe o singură tabelă scrie în firmă
        // exact ca importul întreg, deci n-are voie să aducă luni pe care importul întreg
        // le-ar fi lăsat în SAGA.
        stabilesteLimita(ctx, archive);
        java.util.Properties sesiune = ctx.intraInSesiune();
        try {
            TableReport rep = imp.run(archive, ctx);
            // A67 (D14): «cu copiii ei», cum spune descrierea — copiii rulează imediat după, cu linia lor de final
            for (SagaTableImporter copil : ImportRegistry.childrenOf(imp.tableName())) {
                TableReport rc = copil.run(archive, ctx);
                SagaLog.line("   ↳ " + (rc.isEmptyTable() && rc.errors() == 0 && rc.dupaLimita() == 0 && rc.orfane() == 0
                    ? copil.tableName() + " sursă=0 (tabelă goală în arhivă)" : rc.toString()));
            }
            return rep;
        } finally {
            ImportCtx.iesiDinSesiune(sesiune);
        }
    }

