def _source_manifest(source: str, current: list[dict]) -> list[dict]:
    """Marchează fișierele pe care readerul le poate vedea efectiv din sursa aleasă."""
    visible = set()
    if os.path.isfile(source):
        visible.add(os.path.basename(source))
    else:
        for name in os.listdir(source):
            path = os.path.join(source, name)
            if os.path.isfile(path):
                visible.add(name)
    out = []
    for item in current:
        base = os.path.basename(item.get("name") or "")
        item = dict(item)
        item["visible_to_parser"] = base in visible or item.get("name") in visible
        out.append(item)
    return out


