def _iter_source_files(source: str):
    if os.path.isfile(source):
        yield source
        return
    for root, _dirs, names in os.walk(source):
        for name in sorted(names):
            yield os.path.join(root, name)


def _identity_from_saft(xml_path: str) -> dict:
    """Extrage {name, cui} din header-ul SAF-T D406 (fiabil). Gol dacă fișierul nu e SAF-T."""
    try:
        _ensure_saga_on_path()
        from saga_migration.saft_parse import SAFTParser
        p = SAFTParser(xml_path)
        cui = p.get_company_cui()
        name = ""
        header = p.root.find(p._tag("Header"))
        comp = header.find(p._tag("CompanyHeader")) if header is not None else None
        if comp is not None:
            for cand in ("Name", "CompanyName"):
                el = comp.find(p._tag(cand))
                if el is not None and el.text and el.text.strip():
                    name = el.text.strip()
                    break
        if cui or name:
            return {"name": name, "cui": cui, "source": "saf-t"}
    except Exception:  # noqa: BLE001 — inspecție best-effort, nu blocăm pe un XML ne-SAF-T
        pass
    return {}


def _identity_from_setari(dbf_path: str, encoding: str) -> dict:
    """Best-effort din SETARI_G/SETARI.dbf (perechi cheie-valoare): caută CUI + denumire firmă.
    Rezultatul e VERIFICAT oricum la ANAF în pasul următor, deci un fals-pozitiv nu e periculos."""
    try:
        from dbfread import DBF
        try:
            table = DBF(dbf_path, encoding=encoding, load=True, char_decode_errors="replace")
        except Exception:  # noqa: BLE001
            table = DBF(dbf_path, encoding="cp852", load=True, char_decode_errors="replace")
        cui = ""
        name = ""
        for rec in table:
            d = {str(k).upper(): ("" if v is None else str(v)) for k, v in dict(rec).items()}
            key = (d.get("CHEIE") or d.get("NUME") or d.get("PARAM") or "").upper()
            val = (d.get("VALOARE") or d.get("VAL") or "").strip()
            if not val:
                continue
            if not cui and any(t in key for t in ("FISCAL", "CUI", "CIF")):
                m = re.search(r"(\d{2,10})", val)
                if m:
                    cui = m.group(1)
            if not name and any(t in key for t in ("DENUMIRE", "FIRMA", "UNITATE")):
                name = val
        if cui or name:
            return {"name": name, "cui": cui, "source": "setari"}
    except Exception:  # noqa: BLE001
        pass
    return {}


